css:
@page {
  size: A4;
  margin: 0;
}

.print-format {
  padding: 0 !important;
  margin: 0 !important;
  margin-top: 0mm !important;
  margin-bottom: 0mm !important;
  margin-left: 0mm !important;
  margin-right: 0mm !important;
  min-height: 0 !important;
  max-width: none !important;
}

.action-banner {
  display: none !important;
  height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  overflow: hidden !important;
}

.print-format-gutter {
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  background: transparent !important;
}

.print-format-preview {
  padding: 0 !important;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html,
body {
  margin: 0;
  padding: 0;
}

.print-page {
  width: 210mm;
  height: 297mm;
  position: relative;
  overflow: hidden;

  background-image: var(--page-bg);
  background-repeat: no-repeat;
  background-position: center center;
  background-size: 210mm 297mm;

  page-break-after: always;
}

.print-page:last-child {
  page-break-after: auto;
}

.field {
  position: absolute;
  font-size: 10px;
  line-height: 1.25;
  color: #000;
  white-space: normal;
}

.field-quote-no {
  top: 44mm;
  left: 156mm;
  width: 46mm;
  text-align: center;
  font-size: 9px;
}

.field-customer {
