}

.item-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  font-size: 9px;
  color: #000;
}

.item-table td {
  border: none;
  padding: 1.5mm;
  vertical-align: top;
  line-height: 1.3;
}

.col-no {
